<?php
if(!isset($user,$requests)||!$user){http_response_code(404);exit;}
$month=query_text('month',date('Y-m'));$first=preg_match('/^\d{4}-\d{2}$/D',$month)?DateTimeImmutable::createFromFormat('!Y-m-d',$month.'-01'):false;
if(!$first||$first->format('Y-m')!==$month||$month<'2020-01'||$month>'2100-12'){$first=new DateTimeImmutable(date('Y-m-01'));$month=$first->format('Y-m');}
$last=$first->modify('last day of this month');$today=date('Y-m-d');$approved=array_values(array_filter($requests,fn($r)=>$r['status']==='Approved'));
$events=array_values(array_filter($approved,fn($r)=>$r['start_date']<=$last->format('Y-m-d')&&$r['end_date']>=$month.'-01'));
usort($events,fn($a,$b)=>($a['start_date']<=>$b['start_date'])?:($a['name']<=>$b['name']));
$ongoing=array_values(array_filter($approved,fn($r)=>$r['start_date']<=$today&&$r['end_date']>=$today));
?>
<div class="page-heading"><p class="eyebrow">KNOW WHO’S AWAY</p><h1>Leave Calendar</h1><p class="muted"><?= $admin?'All employees’ approved leave.':'Your approved leave.' ?> Weekdays only.</p></div>
<section class="panel"><h2><?= $admin?'Employees Away Today':'Your Current Leave' ?></h2><?php if(!$ongoing):?><p class="muted">No approved leave today.</p><?php else:?><div class="ongoing-list"><?php foreach($ongoing as $r):?><article><strong><?= e($r['name']) ?></strong><span><?= e(leave_label($r['leave_type'])) ?> · Until <?= e($r['end_date']) ?></span><small><?= e(leave_timing($r)) ?></small></article><?php endforeach ?></div><?php endif ?><?php if((int)date('N')>5):?><small class="muted">Today is a weekend. Approved periods may span non-working days.</small><?php endif ?></section>
<section class="panel"><div class="calendar-toolbar"><h2><?= e($first->format('F Y')) ?></h2><div class="button-group"><a class="text-link" aria-label="Previous Month" href="index.php?view=calendar&amp;month=<?= e($first->modify('-1 month')->format('Y-m')) ?>">← Previous</a><a class="text-link" href="index.php?view=calendar">Today</a><a class="text-link" aria-label="Next Month" href="index.php?view=calendar&amp;month=<?= e($first->modify('+1 month')->format('Y-m')) ?>">Next →</a></div></div>
<form method="get" class="table-tools"><input type="hidden" name="view" value="calendar"><label>Choose Month<input type="month" name="month" min="2020-01" max="2100-12" value="<?= e($month) ?>" required></label><button class="button">View Month</button></form>
<div class="calendar-scroll" role="region" aria-label="Monthly leave calendar" tabindex="0"><div class="leave-calendar"><div class="calendar-weekdays"><?php foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $day):?><b><?= $day ?></b><?php endforeach ?></div><div class="calendar-days">
<?php for($blank=1;$blank<(int)$first->format('N');$blank++):?><div class="calendar-blank" aria-hidden="true"></div><?php endfor ?>
<?php for($date=$first;$date<=$last;$date=$date->modify('+1 day')):$iso=$date->format('Y-m-d');$weekend=(int)$date->format('N')>5;?><div class="calendar-day <?= $weekend?'calendar-weekend':'' ?> <?= $iso===$today?'calendar-today':'' ?>"><time datetime="<?= $iso ?>"><?= $date->format('j') ?><?= $iso===$today?' · Today':'' ?></time><?php if(!$weekend):foreach($events as $r):if($r['start_date']<=$iso&&$r['end_date']>=$iso):?><a class="calendar-event" href="#calendar-request-<?= (int)$r['id'] ?>"><b><?= e($r['name']) ?></b><span><?= e(leave_label($r['leave_type'])) ?></span></a><?php endif;endforeach;endif ?></div><?php endfor ?></div></div></div>
<h2 class="calendar-agenda-title">Leaves This Month</h2><p class="muted">Approved periods. Weekends are excluded from charged days.</p><?php if(!$events):?><p>No approved leaves this month.</p><?php else:?><div class="calendar-agenda"><?php foreach($events as $r):?><article id="calendar-request-<?= (int)$r['id'] ?>"><strong><?= e($r['name']) ?> · <?= e(leave_label($r['leave_type'])) ?></strong><p><?= e($r['start_date']) ?> → <?= e($r['end_date']) ?> · <?= leave_duration($r) ?> <?= $r['leave_type']==='Fast'?'day · Half-day':'weekdays' ?></p><small><?= e(leave_timing($r)) ?></small></article><?php endforeach ?></div><?php endif ?></section>
